import type { Block, DocFile } from "./types";

const LOGO_B64 = "";

const CSS = `

  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800;900&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --orange:   #E85D26;
    --orange2:  #C2420A;
    --dark:     #111111;
    --dark2:    #1a1a1a;
    --grey:     #f5f5f5;
    --border:   #e5e7eb;
    --text:     #222222;
    --muted:    #666666;
    --light-o:  #fff8f5;
    --mono:     'JetBrains Mono', 'Courier New', monospace;
  }

  body {
    font-family: 'Inter', Arial, sans-serif;
    background: #f0f0f0;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    color: var(--text);
    font-size: 13px;
    line-height: 1.6;
    padding: 32px 16px 64px;
  }

  .page {
    max-width: 720px;
    margin: 0 auto;
    background: #ffffff;
    border-radius: 10px;
    overflow: hidden;
    box-shadow: 0 4px 32px rgba(0,0,0,0.10);
    border-top: 4px solid var(--orange);
    border-bottom: 4px solid var(--orange);
  }

  /* ── Header ── */
  .header {
    background: var(--dark2);
    padding: 24px 40px;
    border-bottom: 1px solid var(--orange);
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .header-logo {
    font-family: var(--mono);
    font-size: 20px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.5px;
  }
  .header-logo span { color: var(--orange); }
  .header-badge {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--orange);
    border: 1px solid var(--orange);
    border-radius: 20px;
    padding: 3px 10px;
  }

  /* ── Cover ── */
  .cover {
    padding: 36px 40px 28px;
    border-bottom: 1px solid var(--border);
  }
  .cover-label {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--orange);
    margin-bottom: 10px;
  }
  .cover-title {
    font-size: 28px;
    font-weight: 800;
    color: var(--dark);
    line-height: 1.15;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }
  .cover-title em { color: var(--orange); font-style: normal; }
  .cover-subtitle {
    font-size: 13px;
    color: var(--muted);
    margin-bottom: 24px;
    max-width: 480px;
    line-height: 1.7;
  }
  .cover-meta {
    background: var(--grey);
    border-left: 3px solid var(--orange);
    border-radius: 0 6px 6px 0;
    padding: 14px 18px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }
  .meta-item label {
    display: block;
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 4px;
  }
  .meta-item span {
    font-size: 12px;
    font-weight: 600;
    color: var(--dark);
  }

  /* ── Body ── */
  .body { padding: 32px 40px; }

  /* ── Section ── */
  .section { margin-bottom: 28px; break-inside: avoid; }
  .section-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border);
  }
  .section-num {
    width: 26px; height: 26px;
    background: var(--orange);
    color: white;
    font-size: 11px;
    font-weight: 800;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-family: var(--mono);
  }
  .section-title {
    font-size: 15px;
    font-weight: 700;
    color: var(--dark);
  }

  /* ── Sub section label ── */
  .sub-label {
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 8px;
    margin-top: 14px;
  }

  /* ── KV Table ── */
  .kv-table {
    width: 100%;
    background: var(--light-o);
    border-left: 3px solid var(--orange);
    border-radius: 0 6px 6px 0;
    overflow: hidden;
  }
  .kv-row {
    display: flex;
    align-items: baseline;
    border-top: 1px solid #fde8dc;
    padding: 7px 14px;
  }
  .kv-row:first-child { border-top: none; }
  .kv-key {
    font-size: 11px;
    color: var(--muted);
    width: 38%;
    flex-shrink: 0;
  }
  .kv-val {
    font-size: 11px;
    font-weight: 600;
    color: var(--dark);
    font-family: var(--mono);
    word-break: break-all;
  }

  /* ── Data Table ── */
  .data-table { width: 100%; border-collapse: collapse; font-size: 11px; border-radius: 6px; overflow: hidden; border: 1px solid var(--border); }
  .data-table thead tr { background: var(--dark2); }
  .data-table thead th { padding: 8px 12px; text-align: left; color: #ffffff; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; }
  .data-table tbody tr { border-bottom: 1px solid var(--border); }
  .data-table tbody tr:last-child { border-bottom: none; }
  .data-table tbody td { padding: 7px 12px; color: var(--text); }
  .data-table tbody tr:nth-child(even) td { background: var(--grey); }

  /* ── Checklist ── */
  .checklist { display: flex; flex-direction: column; gap: 4px; }
  .check-item {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    padding: 6px 10px;
    border-radius: 5px;
    background: var(--grey);
    border-left: 3px solid var(--border);
  }
  .check-item.done { border-left-color: #34D399; opacity: 0.7; }
  .check-item.pending { border-left-color: var(--orange); }
  .check-icon {
    width: 14px; height: 14px;
    border-radius: 3px;
    border: 1.5px solid var(--muted);
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    margin-top: 1px;
    font-size: 9px;
    color: white;
    background: transparent;
  }
  .check-item.done .check-icon { background: #34D399; border-color: #34D399; }
  .check-text { font-size: 11px; color: var(--text); line-height: 1.5; }
  .check-item.done .check-text { text-decoration: line-through; color: var(--muted); }

  /* ── Callout / Alert ── */
  .callout {
    background: var(--light-o);
    border-left: 4px solid var(--orange);
    border-radius: 0 6px 6px 0;
    padding: 12px 16px;
    font-size: 12px;
    color: var(--dark);
    display: flex;
    gap: 10px;
    align-items: flex-start;
  }
  .callout-icon { font-size: 14px; flex-shrink: 0; margin-top: 1px; }

  /* ── Code block ── */
  .code-block {
    background: #1a1a1a;
    border-radius: 6px;
    padding: 14px 16px;
    font-family: var(--mono);
    font-size: 10px;
    color: #e8e8e8;
    overflow: hidden;
    border-left: 3px solid var(--orange);
    white-space: pre-wrap;
    word-break: break-all;
    line-height: 1.7;
  }

  /* ── Paragraph ── */
  .paragraph { font-size: 12px; color: #444; line-height: 1.8; }

  /* ── Mapping table ── */
  .mapping-table { width: 100%; border-collapse: collapse; font-size: 10px; }
  .mapping-table thead th { background: var(--dark2); color: #fff; padding: 7px 10px; text-align: left; font-size: 8px; letter-spacing: 1px; text-transform: uppercase; }
  .mapping-table tbody td { padding: 7px 10px; border-bottom: 1px solid var(--border); vertical-align: top; }
  .mapping-table tbody tr:last-child td { border-bottom: none; }
  .status-badge {
    font-size: 8px; font-weight: 700;
    padding: 2px 7px; border-radius: 20px;
    white-space: nowrap; display: inline-block;
  }
  .status-pendente { background: #fff3ed; color: var(--orange); border: 1px solid #fbd5c0; }
  .status-andamento { background: #fff8e1; color: #b45309; border: 1px solid #fde68a; }
  .status-concluido { background: #f0fdf4; color: #166534; border: 1px solid #bbf7d0; }

  /* ── Divider ── */
  .divider { border: none; border-top: 1px solid var(--border); margin: 20px 0; }

  /* ── Footer ── */
  .footer {
    background: var(--dark2);
    border-top: 1px solid var(--orange);
    padding: 20px 40px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .footer-logo {
    font-family: var(--mono);
    font-size: 13px;
    font-weight: 700;
    color: #fff;
  }
  .footer-logo span { color: var(--orange); }
  .footer-text { font-size: 10px; color: #888; text-align: right; line-height: 1.6; }

  /* ── Print ── */
  @media print {
    @page { size: A4; margin: 15mm 12mm; }
    body { background: white !important; padding: 0 !important; margin: 0 !important; }
    .page { box-shadow: none !important; border-radius: 0 !important; max-width: 100% !important; }
    .section { break-inside: avoid; }
  }

`;

// ── Block renderers ─────────────────────────────────────────────────────────
function renderBlock(block: Block): string {
  switch (block.type) {
    case "heading":
      return `<h${block.level ?? 2} style="color:#E85D26;margin:16px 0 8px">${esc(block.text)}</h${block.level ?? 2}>`;

    case "paragraph":
      return `<div class="paragraph">${esc(block.text)}</div>`;

    case "callout":
      return `<div class="callout" style="margin-bottom:8px"><span class="callout-icon">⚠</span><div>${esc(block.text)}</div></div>`;

    case "keyvalue": {
      const rows = block.items.map(it =>
        `<div class="kv-row"><span class="kv-key">${esc(it.key)}</span><span class="kv-val">${esc(it.value)}</span></div>`
      ).join("");
      return `${block.title ? `<div class="sub-label">${esc(block.title)}</div>` : ""}
        <div class="kv-table" style="margin-bottom:12px">${rows}</div>`;
    }

    case "table": {
      const headers = block.columns.map(c => `<th>${esc(c)}</th>`).join("");
      const rows = block.rows.map(r =>
        `<tr>${r.cells.map(cell => `<td>${esc(cell)}</td>`).join("")}</tr>`
      ).join("");
      return `<div style="overflow:auto;margin-bottom:12px">
        <table class="data-table"><thead><tr>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;
    }

    case "mapping": {
      const headers = ["Plataforma","Ação","Status","Observações"].map(h => `<th>${h}</th>`).join("");
      const rows = block.items.map(it =>
        `<tr>
          <td>${esc(it.platform)}</td>
          <td>${esc(it.action)}</td>
          <td><span class="status-badge status-${it.status === "Concluído" ? "concluido" : it.status === "Em andamento" ? "andamento" : "pendente"}">${esc(it.status)}</span></td>
          <td>${esc(it.notes)}</td>
        </tr>`
      ).join("");
      return `<div style="overflow:auto;margin-bottom:12px">
        <table class="mapping-table"><thead><tr>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;
    }

    case "endpoints":
      return block.items.map(e => `
        <div style="background:var(--light-o);border-left:4px solid var(--orange);border-radius:0 6px 6px 0;padding:12px 14px;margin-bottom:8px">
          <div style="font-weight:700;font-size:12px;margin-bottom:4px">
            <span style="background:var(--orange);color:#fff;padding:2px 6px;border-radius:3px;font-size:10px;font-family:var(--mono)">${esc(e.method)}</span>
            <span style="font-family:var(--mono);font-size:11px;margin-left:8px">${esc(e.path)}</span>
          </div>
          ${e.description ? `<div style="font-size:11px;color:var(--muted)">${esc(e.description)}</div>` : ""}
        </div>`).join("");

    case "code":
      return `<div class="code-block">${esc(block.code)}</div>`;

    default:
      return "";
  }
}

function renderSection(section: { title: string; blocks: Block[] }, idx: number): string {
  const blocks = section.blocks.map(renderBlock).join("\n");
  return `
    <div class="section">
      <div class="section-header">
        <div class="section-num">${String(idx + 1).padStart(2, "0")}</div>
        <div class="section-title">${esc(section.title)}</div>
      </div>
      ${blocks}
    </div>`;
}

function esc(s?: string): string {
  return (s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

export function exportPdf(doc: DocFile): void {
  const meta = doc.meta ?? {};
  const sections = (doc.sections ?? []).map((s, i) => renderSection(s, i)).join("\n");

  const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>${esc(doc.title || "Documentação")}</title>
<style>${CSS}</style>
</head>
<body>
<div class="page">

  <div class="header">
    <img src="data:image/png;base64,${LOGO_B64}" alt="Rvops" style="height:32px;width:auto;display:block;mix-blend-mode:screen"/>
    <div class="header-badge">Documentação Técnica</div>
  </div>

  <div class="cover">
    <div class="cover-label">● Rvops · CRM Integrations</div>
    <div class="cover-title">${esc(doc.title || "Documentação")}</div>
    ${doc.subtitle ? `<div class="cover-subtitle">${esc(doc.subtitle)}</div>` : ""}
    <div class="cover-meta">
      <div class="meta-item"><label>Cliente</label><span>${esc(meta.client)}</span></div>
      <div class="meta-item"><label>Projeto</label><span>${esc(meta.projectName)}</span></div>
      <div class="meta-item"><label>Responsável</label><span>${esc(meta.owner)}</span></div>
      <div class="meta-item"><label>Data</label><span>${esc(meta.date || new Date().toLocaleDateString("pt-BR"))}</span></div>
    </div>
  </div>

  <div class="body">
    ${sections}
  </div>

  <div class="footer">
    <img src="data:image/png;base64,${LOGO_B64}" alt="Rvops" style="height:22px;width:auto;mix-blend-mode:screen"/>
    <span style="font-family:\'JetBrains Mono\',monospace;font-size:9px;font-weight:500;letter-spacing:0.25em;text-transform:uppercase;color:#888;margin-left:12px">DOCS · STUDIO</span>
  </div>

</div>
</body>
</html>`;

  // Inject → print (synchronous, blocks until dialog closes) → remove
  const container = document.createElement("div");
  container.id = "__pdf_print__";
  container.innerHTML = html;

  const style = document.createElement("style");
  style.textContent = `
    @media print {
      body > *:not(#__pdf_print__) { display: none !important; }
      #__pdf_print__ { display: block !important; }
      #__pdf_print__ .page {
        box-shadow: none !important;
        border-radius: 0 !important;
        max-width: 100% !important;
        background: white !important;
      }
    }
    #__pdf_print__ { display: none; position: fixed; }
  `;

  document.head.appendChild(style);
  document.body.appendChild(container);

  // window.print() is synchronous — blocks until user closes dialog
  window.print();

  // Cleanup immediately after dialog closes
  container.remove();
  style.remove();
}
